if(-not$OutputDirectory){$OutputDirectory=Join-Path ([IO.Path]::GetDirectoryName([IO.Path]::GetDirectoryName($RepositoryRoot))) ('analysis-cache/chunk7-continuation/assisted-connection-'+[Guid]::NewGuid().ToString('N'))}
if(Test-Path -LiteralPath $OutputDirectory){throw 'Fresh focused output required.'};[void][IO.Directory]::CreateDirectory($OutputDirectory)
$inputs=[Collections.Generic.Dictionary[string,string]]::new([StringComparer]::OrdinalIgnoreCase)
function Source([string]$Relative){$p=Join-Path $RepositoryRoot $Relative;if($SourceOverlayRoot){$candidate=Join-Path $SourceOverlayRoot $Relative;if(Test-Path -LiteralPath $candidate){$p=$candidate}};$p=[IO.Path]::GetFullPath($p);$inputs[$p]=(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant();$p}
function Write-ConnectionFile([string]$Leaf,[string]$Text){$p=Join-Path $OutputDirectory $Leaf;[IO.File]::WriteAllText($p,$Text,[Text.UTF8Encoding]::new($false));$p}
function Exact([string]$Text,[string]$Signature){$start=$Text.IndexOf($Signature,[StringComparison]::Ordinal);if($start-lt0){throw ('Missing actual method '+$Signature)};$open=$Text.IndexOf('{',$start);$end=$open+1;$depth=1;while($depth-and$end-lt$Text.Length){if($Text[$end]-ceq'{'){$depth++}elseif($Text[$end]-ceq'}'){$depth--};$end++};if($depth){throw 'Unbalanced actual method.'};$Text.Substring($start,$end-$start)}
$compiler='C:/Program Files (x86)/Microsoft Visual Studio/2022/BuildTools/MSBuild/Current/Bin/Roslyn/csc.exe';$framework='C:/Program Files (x86)/Reference Assemblies/Microsoft/Framework/.NETFramework/v4.7';$json='C:/Program Files (x86)/Steam/steamapps/common/Pathfinder Kingmaker/Kingmaker_Data/Managed/Newtonsoft.Json.dll'
foreach($p in @($compiler,$json)+@('mscorlib.dll','System.dll','System.Core.dll','Microsoft.CSharp.dll'|ForEach-Object{Join-Path $framework $_})){$inputs[$p]=(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant()}
function Compile-Connection([string]$Name,[string]$Main,[string[]]$Sources,[switch]$UseJson){$exe=Join-Path $OutputDirectory ($Name+'.exe');$args=@('/nologo','/target:exe','/langversion:7.3','/nostdlib+','/deterministic+','/optimize+','/nowarn:0649',('/main:'+$Main),('/out:'+$exe));$args+=@('mscorlib.dll','System.dll','System.Core.dll','Microsoft.CSharp.dll')|ForEach-Object{'/reference:'+(Join-Path $framework $_)};if($UseJson){$args+=('/reference:'+$json)};$rsp=Write-ConnectionFile ($Name+'.rsp') (($args+@($Sources)|ForEach-Object{'"'+$_+'"'})-join[Environment]::NewLine);$global:LASTEXITCODE=0;&$compiler /noconfig ('@'+$rsp) > (Join-Path $OutputDirectory ($Name+'-compile.log'));if($global:LASTEXITCODE-ne0){throw ('Actual '+$Name+' compile failed.')};$exe}
$watch=[Diagnostics.Stopwatch]::StartNew();$sources=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
$authorityPath=Source 'src/KingmakerMountedCombat/Diagnostics/PersistenceSaveAuthorization.cs';$authority=[IO.File]::ReadAllText($authorityPath)
$authority=$authority.Replace((Exact $authority '        private static void RequireDirectory(string path)'),'        private static void RequireDirectory(string path) { KingmakerMountedCombat.Tests.BootstrapVirtualStorage.RequireDirectory(path); }').Replace((Exact $authority '        private static string ReadOwnedHash(string path)'),'        private static string ReadOwnedHash(string path) { return KingmakerMountedCombat.Tests.BootstrapVirtualStorage.Hash(path); }')
