foreach($node in $project.SelectNodes("//*[local-name()='Compile']")){$original=[IO.Path]::GetFullPath((Join-Path (Join-Path $RepositoryRoot 'tests') $node.Include));$relative=$original.Substring($RepositoryRoot.TrimEnd('/','\').Length+1).Replace('\','/');if((Split-Path -Leaf $original)-ceq'PersistenceSaveAuthorization.cs'){$p=$actualAuthority}else{$p=Source $relative};[void]$sources.Add($p)}
$test=Source 'tests/Chunk7Diagnostics/AssistedAcquisitionConnectionProtocolTests.cs';[void]$sources.Add($test)
if($Scope-ceq'All'){$protocol=Compile-Connection 'protocol' 'KingmakerMountedCombat.Tests.AssistedAcquisitionConnectionProtocolTests' @($sources)}
$rows=@();function Run-Connection([string]$Name,[string]$Executable,[string[]]$Arguments,[string]$Pattern){$log=Join-Path $OutputDirectory ($Name+'.log');$global:LASTEXITCODE=0;$ErrorActionPreference='Continue';&$Executable @Arguments *> $log;$exit=$global:LASTEXITCODE;$ErrorActionPreference='Stop';$raw=Get-Content -LiteralPath $log -Raw;$m=[regex]::Match($raw,$Pattern);if($exit-ne0-or-not$m.Success-or[int]$m.Groups[1].Value-le0-or[int]$m.Groups[2].Value-ne0){throw ('Actual '+$Name+' failed: '+$raw)};[pscustomobject]@{name=$Name;pass=[int]$m.Groups[1].Value;fail=0;exitCode=$exit;log=$log}}
if($Scope-ceq'All'){$rows+=Run-Connection 'protocol' $protocol @() 'TOTAL PASS=(\d+) FAIL=(\d+)'}
$fixturePath=Source 'tests/Chunk7Diagnostics/AssistedAcquisitionConnectionFixture.json';$fixture=[IO.File]::ReadAllText($fixturePath)|ConvertFrom-Json
$producer=Write-ConnectionFile 'producer.json' ($fixture.producer|ConvertTo-Json -Depth 90);$cold=Write-ConnectionFile 'cold.json' ($fixture.cold|ConvertTo-Json -Depth 90)
$sourcePath=Source 'src/KingmakerMountedCombat/Diagnostics/Chunk7ManualDerivedScenario.Assisted.cs';$source=[IO.File]::ReadAllText($sourcePath)
$methods=(Exact $source 'internal static JObject RequireAssistedCumulativeSource')+[Environment]::NewLine+[regex]::Match($source,'private static bool AssistedTrue[^\r\n]+').Value+[Environment]::NewLine+[regex]::Match($source,'private static bool AssistedFalse[^\r\n]+').Value+[Environment]::NewLine+(Exact $source 'private static void RequireAssistedEnvelope')
$templatePath=Source 'tests/Chunk7Diagnostics/AssistedAcquisitionConnectionSourceTemplate.cs';$actual=Write-ConnectionFile 'ActualProjection.cs' ([IO.File]::ReadAllText($templatePath).Replace('__ACTUAL_METHODS__',$methods));[void]$sources.Add($actual)
$projection=Compile-Connection 'projection' 'KingmakerMountedCombat.Tests.AssistedAcquisitionConnectionSourceTests' @($sources) -UseJson
$loaderText='using System;using System.Reflection;static class Loader{static int Main(string[] args){var json=Assembly.LoadFrom(@"'+$json+'");AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>e.Name==json.FullName?json:null;return (int)Assembly.LoadFrom(args[0]).EntryPoint.Invoke(null,new object[]{new string[]{args[1],args[2],args[3]}});}}'
$loaderSource=Write-ConnectionFile 'Loader.cs' $loaderText;$loader=Compile-Connection 'loader' 'Loader' @($loaderSource)
$rows+=Run-Connection 'projection' $loader @($projection,$producer,$cold,$OutputDirectory) 'TOTAL PASS=(\d+) FAIL=(\d+)'
$smallPath=Source 'src/KingmakerMountedCombat/Diagnostics/Chunk7SmallCalibrationScenario.Manual.cs';$small=[IO.File]::ReadAllText($smallPath);$scenario=[IO.File]::ReadAllText((Source 'src/KingmakerMountedCombat/Diagnostics/Chunk7SmallCalibrationScenario.cs'))
$prior=(Exact $small 'private void BindAssistedManualPriorPair()')+[Environment]::NewLine+(Exact $small 'private JObject CaptureAssistedManualPriorPair()')+';'+[Environment]::NewLine+(Exact $small 'private void RequireAssistedManualPriorPair()')+[Environment]::NewLine+(Exact $small 'private JObject CaptureManualResources()')+';'
$smallTemplate=[IO.File]::ReadAllText((Source 'tests/Chunk7Diagnostics/AssistedSmallManualRosterAdapterTemplate.cs'))
$smallActual=$smallTemplate.Replace('/*CAPTURE*/',(Exact $small 'private UnitEntityData[] CaptureManualFieldRoster()')).Replace('/*IDENTITY*/',(Exact $small 'private void RequireManualFieldIdentity()')).Replace('/*EXACT*/',(Exact $scenario 'private UnitEntityData Exact(string id)')).Replace('/*PRIOR*/',$prior)+[Environment]::NewLine+'internal static class Entry{internal static int Main(string[] args)=>ActualSmallRoster.Verify();}'
$smallGenerated=Write-ConnectionFile 'ActualSmall.cs' $smallActual;$helper=Source 'src/KingmakerMountedCombat/Diagnostics/Chunk7NativeFieldRoster.cs'
$smallExe=Compile-Connection 'small' 'Entry' @($smallGenerated,$helper) -UseJson
$rows+=Run-Connection 'small' $loader @($smallExe,$producer,$cold,$OutputDirectory) 'ACTUAL SMALL MANUAL ROSTER PASS (\d+) FAIL (\d+)'
foreach($p in $inputs.Keys){if((Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant()-cne$inputs[$p]){throw 'Input changed during focused checks.'}}
$watch.Stop();$passed=($rows|Measure-Object -Property pass -Sum).Sum
[ordered]@{schemaVersion=1;selectedScope=$Scope;pass=$passed;fail=0;seconds=$watch.Elapsed.TotalSeconds;stages=$rows;inputs=@($inputs.GetEnumerator()|Sort-Object Key|ForEach-Object{[ordered]@{path=$_.Key;sha256=$_.Value}});nativeInvoked=$false;archiveReads=0;boundaries=@('Actual request/authority with external file and directory facades.','Actual source admission/projector against formatter-derived generated JSON; source qualification and native inventory are explicit external boundaries.','Actual prior-pair capture and custody, native object metadata and unrelated arrangement facade.')}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $OutputDirectory 'receipt.json') -Encoding UTF8
